mapper.update:
UPDATE evaluation_run
SET is_baseline = 0,
    baseline_name = NULL
WHERE user_id = #{userId}
  AND eval_set_version = #{evalSetVersion}
  AND eval_set_hash = #{evalSetHash}
  AND is_baseline = 1

UPDATE evaluation_run
SET is_baseline = 1,
    baseline_name = #{baselineName}
WHERE user_id = #{userId}
  AND run_id = #{runId}
  AND passed = 1
